84	        $this->status = OrderStatus::Draft;
85	        $this->lines = new ArrayCollection();
86	        $this->discount = Money::zero($currency);
87	    }
88	
89	    public static function place(OrderId $id, CustomerId $customerId, Currency $currency = Currency::CZK): self
90	    {
91	        $order = new self($id, $customerId, $currency);
92	        $order->record(new OrderPlaced($id, $customerId, new \DateTimeImmutable()));
93	
94	        return $order;
95	    }
96	
97	    public function addItem(ProductId $productId, int $quantity, Money $unitPrice): void
98	    {
99	        if ($this->status !== OrderStatus::Draft) {
100	            throw InvalidOrderStateTransitionException::notAllowedInState('addItem', $this->status->value);
101	        }
102	
103	        $this->assertSameCurrency($unitPrice);
104	
105	        // Jedna položka na produkt: množství se sčítá, položka se neduplikuje.
106	        foreach ($this->lines as $existing) {
107	            if ($existing->productId->equals($productId)) {
108	                $existing->increaseQuantity($quantity);
109	                $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
110	
111	                return;
112	            }
113	        }
114	
115	        $this->lines->add(new OrderItem($this, $productId, $quantity, $unitPrice));
116	        $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
117	    }
118	
119	    public function changeItemQuantity(ProductId $productId, int $quantity): void
120	    {
121	        if ($this->status !== OrderStatus::Draft) {
122	            throw InvalidOrderStateTransitionException::notAllowedInState('changeItemQuantity', $this->status->value);
123	        }
124	
125	        if ($quantity < 1) {
126	            throw InvalidQuantityException::mustBePositive($quantity);
127	        }
128	
129	        $this->itemFor($productId)->changeQuantity($quantity);
130	        $this->record(new OrderItemQuantityChanged($this->id, $productId, $quantity, new \DateTimeImmutable()));
131	    }
132	
133	    public function removeItem(ProductId $productId): void
134	    {
135	        if ($this->status !== OrderStatus::Draft) {
136	            throw InvalidOrderStateTransitionException::notAllowedInState('removeItem', $this->status->value);
137	        }
138	
139	        $item = $this->itemFor($productId);
140	        if ($this->lines->count() === 1) {
141	            throw LastItemCannotBeRemovedException::forProduct($productId);
142	        }
143	
144	        // Sleva nesmí po odebrání přesáhnout nový součet položek.
145	        $newTotal = $this->totalAmount()->subtract($item->subtotal());
146	        if ($this->discount->amountInCents > $newTotal->amountInCents) {
147	            throw DiscountExceedsItemsTotalException::forItemsTotal($this->discount, $newTotal);
148	        }
149	
150	        $this->lines->removeElement($item);
151	        $this->record(new OrderItemRemoved($this->id, $productId, new \DateTimeImmutable()));
152	    }
153	
154	    public function applyDiscount(Money $discount): void
155	    {
156	        if ($this->status !== OrderStatus::Draft) {
157	            throw InvalidOrderStateTransitionException::notAllowedInState('applyDiscount', $this->status->value);
158	        }
159	
160	        $this->assertSameCurrency($discount);
161	
162	        $total = $this->totalAmount();
163	        if ($discount->amountInCents > $total->amountInCents) {
164	            throw DiscountExceedsItemsTotalException::forItemsTotal($discount, $total);
165	        }
166	
167	        $this->discount = $discount;
168	    }
169	
170	    public function confirm(?\DateTimeImmutable $at = null): void
171	    {
172	        if (!$this->status->canTransitionTo(OrderStatus::Confirmed)) {
173	            throw InvalidOrderStateTransitionException::cannotTransition(
174	                $this->status->value,
175	                OrderStatus::Confirmed->value,
176	            );
177	        }
178	
179	        if ($this->lines->isEmpty()) {
180	            throw EmptyOrderException::cannotConfirm();
181	        }
182	
183	        $this->status = OrderStatus::Confirmed;
184	        $this->placedAt = $at ?? new \DateTimeImmutable();
185	        $this->record(new OrderConfirmed($this->id, $this->customerId, $this->placedAt));
186	    }
187	
188	    public function markPaid(): void
189	    {
190	        // Opakované doručení příkazu o platbě není chyba volajícího.
191	        if ($this->status === OrderStatus::Paid) {
192	            return;
193	        }
194	
195	        if (!$this->status->canTransitionTo(OrderStatus::Paid)) {
196	            throw InvalidOrderStateTransitionException::cannotTransition(
197	                $this->status->value,
198	                OrderStatus::Paid->value,
199	            );
200	        }
201	
202	        $this->status = OrderStatus::Paid;
203	        $this->record(new OrderPaid($this->id, new \DateTimeImmutable()));
204	    }
205	
206	    public function ship(): void
207	    {
208	        if ($this->status === OrderStatus::Shipped) {
209	            return;
210	        }
211	
212	        if (!$this->status->canTransitionTo(OrderStatus::Shipped)) {
213	            throw InvalidOrderStateTransitionException::cannotTransition(
214	                $this->status->value,
215	                OrderStatus::Shipped->value,
216	            );
217	        }
218	
219	        $this->status = OrderStatus::Shipped;
220	        $this->record(new OrderShipped($this->id, new \DateTimeImmutable()));
221	    }
222	
223	    public function deliver(): void
224	    {
225	        if (!$this->status->canTransitionTo(OrderStatus::Delivered)) {
226	            throw InvalidOrderStateTransitionException::cannotTransition(
227	                $this->status->value,
228	                OrderStatus::Delivered->value,
229	            );
230	        }
231	
232	        $this->status = OrderStatus::Delivered;
233	        $this->record(new OrderDelivered($this->id, new \DateTimeImmutable()));
234	    }
235	
236	    // Čas přichází zvenku, aby šel v testech zadat.
237	    public function cancel(string $reason, \DateTimeImmutable $when): void
238	    {
239	        // Opakované storno není chyba volajícího, jen už není co dělat.
240	        if ($this->status === OrderStatus::Cancelled) {
241	            return;
242	        }
243	
244	        // Storno je hrana grafu jako každá jiná: odeslanou ani doručenou
245	        // objednávku zpátky nevrátí.
246	        if (!$this->status->canTransitionTo(OrderStatus::Cancelled)) {
247	            throw InvalidOrderStateTransitionException::cannotTransition(
248	                $this->status->value,
249	                OrderStatus::Cancelled->value,
250	            );
251	        }
252	
253	        // Peníze vrací jen zaplacená objednávka.
254	        if ($this->status === OrderStatus::Paid) {
255	            $this->refundDueInCents = $this->paidAmount()->amountInCents;
256	        }
257	
258	        $this->status = OrderStatus::Cancelled;
259	        $this->cancellationNote = $reason === '' ? null : $reason;
260	        $this->record(new OrderCancelled($this->id, $this->customerId, $reason, $when));
261	    }
262	
263	    public function isOwnedBy(CustomerId $customerId): bool
264	    {
265	        return $this->customerId->equals($customerId);
266	    }
267	
268	    /** Součet položek před slevou. */
269	    public function totalAmount(): Money
270	    {
271	        $total = Money::zero($this->currency);
272	        foreach ($this->lines as $item) {
273	            $total = $total->add($item->subtotal());
274	        }
275	
276	        return $total;
277	    }
278	
279	    /** Částka, kterou zákazník platí: součet položek po slevě. */
280	    public function paidAmount(): Money
281	    {
282	        return $this->totalAmount()
283	            ->subtract($this->discount);
284	    }
285	
286	    private function itemFor(ProductId $productId): OrderItem
287	    {
288	        foreach ($this->lines as $item) {
289	            if ($item->productId->equals($productId)) {
290	                return $item;
291	            }
292	        }
293	
294	        throw OrderItemNotFoundException::forProduct($productId);
295	    }
296	
297	    private function assertSameCurrency(Money $amount): void
298	    {
299	        if ($amount->currency !== $this->currency) {
300	            throw CurrencyMismatchException::forOrder($this->currency, $amount->currency);
301	        }
302	    }
303	}
